export class Base {
  onLifecyclePass: (() => void) | null;
  runLifecycle(): void;
  resetLifecycle(): void;
  getSelectedText(): string;
  selected(): string;
}
export class View extends Base {
  constructor(value: string);
  parent: View | null;
  onLifecyclePass: () => void;
  getSelectedText(): string;
  label(): string;
  label(value: string): View;
}
export class Metrics {
  constructor(count: number, active: boolean);
  count(): number;
  active(): boolean;
}
export class Input {
  private parser;
  push(value: string): void;
  read(): string;
  save(): { read(): string; describe(): string } | null;
  clear(): void;
  close(): void;
  open(): void;
}
export class FactoryInput {
  private parser;
  open(value: string): void;
  close(): void;
  read(): string;
  save(): { describe(): string } | null;
}
export function describeOptions(config: { name: string; required?: boolean; default?: number; type?: string }): string;
export function exerciseCachedStore(): string;
export function exerciseEnvironmentProxy(): string;
